#!/usr/bin/env bash
# Reset the module to a clean state: drop the database, PowerContext state and artifacts.
set -euo pipefail
cd "$(dirname "$0")/.."

rm -rf state
# Generated by ``task plan``; the committed SDD-ORD-004.patch is a deliverable and stays.
rm -f artifacts/diffs/*.plan.json 2>/dev/null || true
# artifacts/records/llm-calls.jsonl and artifacts/logs are kept: they are the recorded
# evidence for this submission. A new ``task plan`` appends to the call record.

# Restore the sample project to its committed (post-change) source.
if [ -d sample-project/snapshots/after/src/orderflow ]; then
  cp -R sample-project/snapshots/after/src/orderflow/. sample-project/src/orderflow/
fi

echo "state removed; sample-project restored to the post-change snapshot"
